// Stress test: N ephemeral wallets register concurrently for one campaign.
//   pnpm stress [--n 200] [--slots 50] [--window 180] [--campaign <id>] [--draw]
// All entrants are SIMULATED: throwaway keys generated by this script, funded by the deployer.
import { mkdirSync, writeFileSync, existsSync, readFileSync } from "node:fs";
import {
  createWalletClient, encodeFunctionData, formatEther, http, parseEventLogs,
  type Address, type Hex,
} from "viem";
import { generatePrivateKey, privateKeyToAccount } from "viem/accounts";
import { disperseAbi, nextAbi } from "./lib/abi.js";
import { chain, publicClient, RPC_URL, CHAIN_ID, CHAIN_NAME, EXPLORER_URL, nextAddress, disperseAddress, deployerKey } from "./lib/env.js";
import { verifyCampaign } from "./verify.js";

// ---------------------------------------------------------------- args
const arg = (name: string, dflt?: string) => {
  const i = process.argv.indexOf(`--${name}`);
  if (i === -1) return dflt;
  const v = process.argv[i + 1];
  return v && !v.startsWith("--") ? v : "true";
};
const N = Number(arg("n", "200"));
const SLOTS = Number(arg("slots", "50"));
const WINDOW_SEC = Number(arg("window", "180"));
const EXISTING = arg("campaign");
const DO_DRAW = arg("draw") === "true";
// Priority fee in gwei (default 0).
const SETTLE_BLOCKS = 10n;
const TIP_GWEI = Number(arg("tip", "0"));
const FUND_CHUNK = 100;

const now = () => performance.now();
const log = (...a: unknown[]) => console.log(`[${new Date().toISOString().slice(11, 23)}]`, ...a);

const deployer = privateKeyToAccount(deployerKey());
const wallet = createWalletClient({ account: deployer, chain, transport: http(RPC_URL) });
const NEXT = nextAddress();

async function send(to: Address, data: Hex, value = 0n) {
  const hash = await wallet.sendTransaction({ to, data, value });
  const r = await publicClient.waitForTransactionReceipt({ hash, pollingInterval: 250 });
  if (r.status !== "success") throw new Error(`tx ${hash} reverted`);
  return r;
}

// ---------------------------------------------------------------- 1. wallets
// --wallets <runId> reuses already-funded wallets from scripts/.wallets/<runId>.json (skips funding).
const REUSE = arg("wallets");
const keys: Hex[] = REUSE
  ? JSON.parse(readFileSync(new URL(`./.wallets/${REUSE}.json`, import.meta.url), "utf8")).slice(0, N)
  : Array.from({ length: N }, () => generatePrivateKey());
const accounts = keys.map((k) => privateKeyToAccount(k));
const runId = new Date().toISOString().replace(/[:.]/g, "-");
mkdirSync(new URL("./.wallets/", import.meta.url), { recursive: true });
if (!REUSE) writeFileSync(new URL(`./.wallets/${runId}.json`, import.meta.url), JSON.stringify(keys));
log(`Generated ${N} ephemeral wallets (keys saved to scripts/.wallets/${runId}.json, gitignored)`);

// ---------------------------------------------------------------- 2. campaign
let campaignId: bigint;
if (EXISTING) {
  campaignId = BigInt(EXISTING);
} else {
  // Created before funding so the gas estimate below runs against a real open campaign;
  // the window must cover funding + the burst.
  const nowSec = BigInt(Math.floor(Date.now() / 1000));
  const r = await send(NEXT, encodeFunctionData({
    abi: nextAbi, functionName: "createCampaign",
    args: [`Stress test #${runId.slice(0, 16)} (simulated entrants)`, SLOTS, nowSec - 5n, nowSec + BigInt(WINDOW_SEC)],
  }));
  const [ev] = parseEventLogs({ abi: nextAbi, logs: r.logs, eventName: "CampaignCreated" });
  campaignId = ev.args.campaignId;
  log(`Created campaign #${campaignId}, drawBlock ${ev.args.drawBlock}`);
}
const campaign = await publicClient.readContract({ address: NEXT, abi: nextAbi, functionName: "getCampaign", args: [campaignId] });

// ---------------------------------------------------------------- 3. fund
const registerData = encodeFunctionData({ abi: nextAbi, functionName: "register", args: [campaignId] });
const est = await publicClient.estimateGas({ account: accounts[0].address, to: NEXT, data: registerData });
const gasLimit = (est * 115n) / 100n; // Monad charges the full gas LIMIT, so keep the margin modest
// Tight fee cap: wallets must hold gasLimit * maxFee, and faucet MON is scarce.
// 10% headroom over the current base fee (Monad testnet sits at its 100 gwei floor).
const { baseFeePerGas } = await publicClient.getBlock();
const maxPriorityFeePerGas = BigInt(Math.round(TIP_GWEI * 1e9));
const maxFeePerGas = (baseFeePerGas! * 110n) / 100n + maxPriorityFeePerGas;
const perWallet = (gasLimit * maxFeePerGas * 103n) / 100n; // small headroom (retries re-sign with +n wei)
log(`register(): estimate ${est} gas, limit ${gasLimit}, maxFee ${maxFeePerGas} wei -> ${formatEther(perWallet)} MON per wallet`);

const bal = await publicClient.getBalance({ address: deployer.address });
// Overhead for the Disperse txs and the draw: Monad charges their full gas limits too.
// Rough gas budget: ~45k per new-account transfer in Disperse, ~70k per drawn slot (from Foundry), plus fixed costs.
const OVERHEAD = (45_000n * BigInt(N) + 1_500_000n + 70_000n * BigInt(SLOTS)) * maxFeePerGas;
const needed = perWallet * BigInt(N);
log(`Deployer ${deployer.address} balance ${formatEther(bal)} MON, wallets need ${formatEther(needed)} MON, reserving ~${formatEther(OVERHEAD)} MON for funding/draw gas`);
if (!REUSE && bal < needed + OVERHEAD) {
  const affordable = Number((bal - OVERHEAD) / perWallet);
  throw new Error(`Not enough MON. With this balance N must be <= ~${affordable}. Re-run with --n ${affordable}.`);
}

const fundStart = now();
let lastFundBlock = 0n;
if (REUSE) lastFundBlock = await publicClient.getBlockNumber();
for (let i = 0; !REUSE && i < N; i += FUND_CHUNK) {
  const chunk = accounts.slice(i, i + FUND_CHUNK).map((a) => a.address);
  ({ blockNumber: lastFundBlock } = await send(disperseAddress(), encodeFunctionData({ abi: disperseAbi, functionName: "disperse", args: [chunk, perWallet] }), perWallet * BigInt(chunk.length)));
  log(`Funded wallets ${i}..${i + chunk.length - 1}`);
}
log(`Funding done in ${((now() - fundStart) / 1000).toFixed(1)} s`);

// Monad executes a few blocks behind consensus and the RPC validates against executed state, so a send right
// after the funding receipt can see a zero balance. Wait until the RPC reports every funded balance.
const visStart = now();
for (;;) {
  // Small sequential chunks: one 180-call batch got rate-limited by the public RPC.
  const bals: bigint[] = [];
  for (let i = 0; i < accounts.length; i += 20) {
    bals.push(...(await Promise.all(accounts.slice(i, i + 20).map((a) => publicClient.getBalance({ address: a.address }).catch(() => -1n)))));
  }
  const missing = bals.filter((b) => b < perWallet).length;
  if (missing === 0) break;
  log(`  ${missing} balances not visible yet`);
  if (now() - visStart > 60_000) throw new Error("Funded balances not visible via RPC after 60 s");
  await new Promise((r) => setTimeout(r, 300));
}
log(`Balances visible via RPC after ${Math.round(now() - visStart)} ms`);
// Observed on Monad testnet (2026-10-12): even once eth_getBalance shows the funds, eth_sendRawTransaction
// rejected txs sent within ~150 ms of the funding receipt with "Signer had insufficient balance" (its check
// runs on slightly lagged state). Waiting a few blocks avoids it.
while ((await publicClient.getBlockNumber({ cacheTime: 0 })) < lastFundBlock + SETTLE_BLOCKS) await new Promise((r) => setTimeout(r, 200));
log(`Waited until ${SETTLE_BLOCKS} blocks after the last funding block`);

// ---------------------------------------------------------------- 4. pre-sign, then fire concurrently
// Retries must re-sign (maxFee + attempt wei): the RPC appears to cache rejections per tx hash, so resending
// identical bytes keeps failing even after the cause is gone (observed on Monad testnet, 2026-10-12).
const sign = (i: number, attempt: number) => accounts[i].signTransaction({
  chainId: CHAIN_ID, type: "eip1559", to: NEXT, data: registerData, nonce: 0, gas: gasLimit,
  maxFeePerGas: maxFeePerGas + BigInt(attempt), maxPriorityFeePerGas,
});
const signed: Hex[] = await Promise.all(accounts.map((_, i) => sign(i, 0)));

type Tx = { i: number; from: Address; hash?: Hex; attempts?: number; sentAt?: number; sendError?: string; seenAt?: number; block?: bigint; status?: string; gasUsed?: bigint };
const txs: Tx[] = accounts.map((a, i) => ({ i, from: a.address }));
const byHash = new Map<string, Tx>();
const blockSeenAt = new Map<bigint, number>();

const startBlock = await publicClient.getBlockNumber();
let watching = true;

// Block watcher: records when each new block (and so each of our txs) first became visible.
const watcher = (async () => {
  let next = startBlock + 1n;
  while (watching) {
    try {
      const head = await publicClient.getBlockNumber({ cacheTime: 0 });
      for (; next <= head; next++) {
        const b = await publicClient.getBlock({ blockNumber: next });
        const t = now();
        blockSeenAt.set(next, t);
        for (const h of b.transactions) {
          const tx = byHash.get(h.toLowerCase());
          if (tx && tx.seenAt === undefined) { tx.seenAt = t; tx.block = next; }
        }
      }
    } catch { /* transient RPC error: retry next tick */ }
    await new Promise((r) => setTimeout(r, 150));
  }
})();

log(`Firing ${N} register() transactions concurrently...`);
const t0 = now();
await Promise.all(signed.map(async (first, i) => {
  const tx = txs[i];
  for (let attempt = 0; attempt < 4; attempt++) {
    const raw = attempt === 0 ? first : await sign(i, attempt);
    try {
      tx.attempts = attempt + 1;
      tx.sentAt ??= now(); // latency is measured from the FIRST attempt
      const hash = await publicClient.request({ method: "eth_sendRawTransaction", params: [raw] });
      tx.hash = hash;
      byHash.set(hash.toLowerCase(), tx);
      tx.sendError = undefined;
      return;
    } catch (e) {
      const err = e as Error & { details?: string; code?: number };
      tx.sendError = [err.message.split("\n")[0], err.code, err.details].filter((x) => x !== undefined).join(" | ");
      // Retry transport errors, and balance rejections (an RPC backend may not have executed the funding block yet).
      if (!/429|rate|timeout|fetch failed|insufficient balance|invalid parameters|RPC Request failed/i.test(tx.sendError)) return;
      await new Promise((r) => setTimeout(r, 400 * (attempt + 1)));
    }
  }
}));
const sendDone = now();
const accepted = txs.filter((t) => t.hash);
log(`RPC accepted ${accepted.length}/${N} in ${((sendDone - t0) / 1000).toFixed(2)} s`);

// Wait until every accepted tx was seen in a block (or 60 s).
const deadline = now() + 60_000;
while (accepted.some((t) => t.seenAt === undefined) && now() < deadline) await new Promise((r) => setTimeout(r, 200));
watching = false;
await watcher;

// Receipts give the final status (included txs can still revert, e.g. reserve-balance rules).
for (let k = 0; k < accepted.length; k += 20) {
  await Promise.all(accepted.slice(k, k + 20).map(async (t) => {
    for (let attempt = 0; attempt < 3; attempt++) {
      try {
        const r = await publicClient.getTransactionReceipt({ hash: t.hash! });
        t.status = r.status; t.block = r.blockNumber; t.gasUsed = r.gasUsed;
        t.seenAt ??= blockSeenAt.get(r.blockNumber) ?? now();
        return;
      } catch { await new Promise((r) => setTimeout(r, 500)); }
    }
    t.status = "not-found";
  }));
}

// ---------------------------------------------------------------- 5. metrics
const confirmed = accepted.filter((t) => t.status === "success");
const reverted = accepted.filter((t) => t.status === "reverted");
const missing = accepted.filter((t) => t.status !== "success" && t.status !== "reverted");
const failedToSend = txs.filter((t) => !t.hash);
const lat = confirmed.map((t) => t.seenAt! - t.sentAt!).sort((a, b) => a - b);
const pct = (p: number) => (lat.length ? lat[Math.min(lat.length - 1, Math.floor((p / 100) * lat.length))] : 0);
const blocks = confirmed.map((t) => t.block!);
const minB = blocks.length ? blocks.reduce((a, b) => (b < a ? b : a)) : 0n;
const maxB = blocks.length ? blocks.reduce((a, b) => (b > a ? b : a)) : 0n;
const lastSeen = confirmed.length ? Math.max(...confirmed.map((t) => t.seenAt!)) : sendDone;
const perBlock: Record<string, number> = {};
for (const b of blocks) perBlock[b.toString()] = (perBlock[b.toString()] ?? 0) + 1;
const onchainCount = await publicClient.readContract({ address: NEXT, abi: nextAbi, functionName: "registrantCount", args: [campaignId] });

const result = {
  label: "SIMULATED ENTRANTS — ephemeral wallets generated and funded by the test script",
  network: CHAIN_NAME,
  chainId: CHAIN_ID,
  rpc: RPC_URL,
  explorer: EXPLORER_URL,
  contract: NEXT,
  campaignId: Number(campaignId),
  campaignName: campaign.name,
  startedAt: new Date(Date.now() - (now() - t0)).toISOString(),
  n: N,
  sent: accepted.length,
  confirmed: confirmed.length,
  reverted: reverted.length,
  notFound: missing.length,
  failedToSend: failedToSend.length,
  retried: txs.filter((t) => (t.attempts ?? 1) > 1).length,
  sendErrors: [...new Set(failedToSend.map((t) => t.sendError))].slice(0, 5),
  registrantsOnChain: Number(onchainCount),
  wallClockMs: Math.round(lastSeen - t0),
  sendPhaseMs: Math.round(sendDone - t0),
  avgConfirmMs: lat.length ? Math.round(lat.reduce((a, b) => a + b, 0) / lat.length) : 0,
  p50ConfirmMs: Math.round(pct(50)),
  p95ConfirmMs: Math.round(pct(95)),
  blockRange: { first: Number(minB), last: Number(maxB), span: blocks.length ? Number(maxB - minB) + 1 : 0 },
  perBlock,
  gas: { estimate: Number(est), limit: Number(gasLimit), maxFeePerGasWei: maxFeePerGas.toString(), usedAvg: confirmed.length ? Math.round(confirmed.reduce((a, t) => a + Number(t.gasUsed ?? 0n), 0) / confirmed.length) : 0 },
  // Times are ms relative to the first send; "confirmMs" = first time the tx's block was visible via RPC.
  timeline: txs.map((t) => ({
    i: t.i, hash: t.hash ?? null, sentMs: t.sentAt ? Math.round(t.sentAt - t0) : null,
    confirmMs: t.seenAt && t.status === "success" ? Math.round(t.seenAt - t0) : null,
    block: t.block ? Number(t.block) : null, status: t.status ?? (t.hash ? "unknown" : "send-failed"),
  })),
  draw: null as null | Record<string, unknown>,
};

log(`sent ${result.sent}, confirmed ${result.confirmed}, reverted ${result.reverted}, failed-to-send ${result.failedToSend}`);
log(`wall clock ${result.wallClockMs} ms, avg confirm ${result.avgConfirmMs} ms (p50 ${result.p50ConfirmMs}, p95 ${result.p95ConfirmMs})`);
log(`blocks ${result.blockRange.first}..${result.blockRange.last} (${result.blockRange.span} blocks)`);

// ---------------------------------------------------------------- 6. optional draw + verify
if (DO_DRAW) {
  const c = await publicClient.readContract({ address: NEXT, abi: nextAbi, functionName: "getCampaign", args: [campaignId] });
  log(`Waiting for drawBlock ${c.drawBlock}...`);
  while ((await publicClient.getBlockNumber({ cacheTime: 0 })) <= c.drawBlock) await new Promise((r) => setTimeout(r, 1000));
  const r = await send(NEXT, encodeFunctionData({ abi: nextAbi, functionName: "draw", args: [campaignId] }));
  const v = await verifyCampaign(campaignId);
  result.draw = { tx: r.transactionHash, block: Number(r.blockNumber), gasUsed: Number(r.gasUsed), seed: v.seed, winners: v.onchain.length, verified: v.seedMatches && v.winnersMatch };
  log(`Drawn in block ${r.blockNumber} (gas ${r.gasUsed}); verifier: ${v.seedMatches && v.winnersMatch ? "MATCH" : "MISMATCH"}`);
}

// ---------------------------------------------------------------- 7. write
const json = JSON.stringify(result, null, 2);
mkdirSync(new URL("./results/", import.meta.url), { recursive: true });
writeFileSync(new URL(`./results/stress-${CHAIN_ID}-${runId}.json`, import.meta.url), json);
// Local dev chains (anvil/hardhat: 31337) never feed the public dashboard.
if (CHAIN_ID !== 31337 && existsSync(new URL("../web/public/", import.meta.url))) {
  mkdirSync(new URL("../web/public/stress/", import.meta.url), { recursive: true });
  writeFileSync(new URL("../web/public/stress/latest.json", import.meta.url), json);
  log("Wrote web/public/stress/latest.json for the dashboard");
}
log(`Wrote scripts/results/stress-${CHAIN_ID}-${runId}.json`);
